'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isfinite = require( '@stdlib/math/base/assert/is-finite' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var abs = require( '@stdlib/math/base/special/abs' );
var epsdiff = require( '@stdlib/math/base/utils/float64-epsilon-difference' );
var toBinaryString = require( '@stdlib/number/float64/base/to-binary-string' );
var EPS = require( '@stdlib/constants/float64/eps' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var gammainc = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( gammainc instanceof Error )
};


// FIXTURES //

var small = require( './fixtures/cpp/small.json' );
var medium = require( './fixtures/cpp/medium.json' );
var large = require( './fixtures/cpp/large.json' );
var huge = require( './fixtures/cpp/huge.json' );


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof gammainc, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided a `NaN`', opts, function test( t ) {
	var val;

	val = gammainc( NaN, 2, true, false );
	t.strictEqual( isnan( val ), true, 'returns expected value' );

	val = gammainc( 4, NaN, true, false );
	t.strictEqual( isnan( val ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns NaN if provided x < 0 or s <= 0', opts, function test( t ) {
	var val;

	// Case: x < 0
	val = gammainc( -0.1, 2, true, false );
	t.strictEqual( isnan( val ), true, 'returns expected value' );

	// Case: s = 0
	val = gammainc( 0.1, 0, true, false );
	t.strictEqual( isnan( val ), true, 'returns expected value' );

	// Case: s < 0
	val = gammainc( 0.1, -2, true, false );
	t.strictEqual( isnan( val ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns 0 for the lower incomplete gamma function when the first argument is zero', opts, function test( t ) {
	var val;
	var s;
	for ( s = 1; s < 10; s++ ) {
		val = gammainc( 0, s, true, false );
		t.strictEqual( val, 0, 'returns expected value' );
	}
	t.end();
});

tape( 'the function correctly evaluates the lower incomplete gamma function for small `x` and small `s`', opts, function test( t ) {
	var expected;
	var actual;
	var delta;
	var tol;
	var b1;
	var b2;
	var x;
	var s;
	var i;

	expected = small.lower_regularized;
	x = small.x;
	s = small.s;

	for ( i = 0; i < x.length; i++ ) {
		actual = gammainc( x[ i ], s[ i ], true, false );

		b1 = isfinite( actual );
		b2 = isfinite( expected[ i ] );
		t.strictEqual( b1, b2, 'returns expected value' );

		b1 = isnan( actual );
		b2 = isnan( expected[ i ] );
		t.strictEqual( b1, b2, 'returns expected value' );
		if ( !b1 || !b2 ) {
			delta = abs( actual - expected[ i ] );
			tol = 80.0 * EPS * abs( expected[ i ] );
			t.ok( delta <= tol, 'within tolerance. x: ' + x[ i ] + ' s: ' + s[ i ] + '. Actual: ' + actual + '. Expected: ' + expected[ i ] + '. Delta: ' + delta + '. Tolerance: ' + tol + '.' );
		}
	}
	t.end();
});

