tape( 'the function correctly evaluates the lower incomplete gamma function for large `x` and small `s`', opts, function test( t ) {
	var expected;
	var actual;
	var b1;
	var b2;
	var x;
	var s;
	var i;

	expected = large.lower_regularized;
	x = large.x;
	s = large.s;

	for ( i = 0; i < x.length; i++ ) {
		actual = gammainc( x[ i ], s[ i ], true, false );

		b1 = isfinite( actual );
		b2 = isfinite( expected[ i ] );
		t.strictEqual( b1, b2, 'returns expected value' );

		b1 = isnan( actual );
		b2 = isnan( expected[ i ] );
		t.strictEqual( b1, b2, 'returns expected value' );
		if ( !b1 || !b2 ) {
			t.strictEqual( actual, expected[ i ], 'returns expected value' );
		}
	}
	t.end();
});

tape( 'the function correctly evaluates the upper incomplete gamma function for large `x` and small `s`', opts, function test( t ) {
	var expected;
	var actual;
	var s1;
	var s2;
	var b1;
	var b2;
	var x;
	var s;
	var i;

	expected = large.upper_regularized;
	x = large.x;
	s = large.s;

	for ( i = 0; i < x.length; i++ ) {
		actual = gammainc( x[ i ], s[ i ], true, true );

		b1 = isfinite( actual );
		b2 = isfinite( expected[ i ] );
		t.strictEqual( b1, b2, 'returns expected value' );

		b1 = isnan( actual );
		b2 = isnan( expected[ i ] );
		t.strictEqual( b1, b2, 'returns expected value' );
		if ( !b1 || !b2 ) {
			// We use bit string comparison for extremely small expected values, as the tolerance becomes smaller than the minimum representable double-precision floating-point value. Out of the 500 values tested, only 16 faced this issue. If those values are excluded, the test passes with a tolerance of `30.0 * EPS`.
			s1 = toBinaryString( actual );
			s2 = toBinaryString( expected[ i ] );
			t.strictEqual( s1.substring( 0, s1.length-12 ), s2.substring( 0, s2.length-12 ), 'returns expected value' );
		}
	}
	t.end();
});

