tape( 'the function correctly evaluates the lower incomplete gamma function for large `x` and medium `s`', opts, function test( t ) {
	var expected;
	var actual;
	var delta;
	var tol;
	var b1;
	var b2;
	var x;
	var s;
	var i;

	expected = huge.lower_regularized;
	x = huge.x;
	s = huge.s;

	for ( i = 0; i < x.length; i++ ) {
		actual = gammainc( x[ i ], s[ i ], true, false );

		b1 = isfinite( actual );
		b2 = isfinite( expected[ i ] );
		t.strictEqual( b1, b2, 'returns expected value' );

		b1 = isnan( actual );
		b2 = isnan( expected[ i ] );
		t.strictEqual( b1, b2, 'returns expected value' );
		if ( !b1 || !b2 ) {
			delta = abs( actual - expected[ i ] );
			tol = EPS * abs( expected[ i ] );
			// Only 1 value in the test suite is not exactly equal to the expected value. If we exclude that value, we can use exact equality for the rest of the values.
			t.ok( delta <= tol, 'within tolerance. x: ' + x[ i ] + ' s: ' + s[ i ] + '. Actual: ' + actual + '. Expected: ' + expected[ i ] + '. Delta: ' + delta + '. Tolerance: ' + tol + '.' );
		}
	}
	t.end();
});

